  this.aja = "\u043a\u043b\u044e\u0447 \u044d\u0442\u043e\u0433\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430, \u0435\u0441\u043b\u0438 \u043d\u0435 \u0432\u043f\u0438\u0441\u0430\u0442\u044c \u0434\u0440\u0443\u0433\u043e\u0439: \u043e\u043d \u043f\u043e\u043a\u0430\u0437\u0430\u043d \u0442\u0430\u043c \u0432 \u00ab\u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u044d\u0442\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e\u00bb";
