  this.aj8 = "\u041d\u043e\u0432\u044b\u0439 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0438\u0439 \u0442\u0435\u043f\u0435\u0440\u044c \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442. \u041d\u0430 \u0442\u043e\u043c \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0435: \u00ab\u0421\u0447\u0435\u0442\u0430\u00bb, \u00ab\u041e\u0442\u043a\u0440\u044b\u0442\u044c \u0438\u043b\u0438 \u0434\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0435\u0449\u0451\u00bb, \u00ab\u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u044d\u0442\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e \u043a \u043c\u043e\u0435\u043c\u0443 \u0441\u0447\u0451\u0442\u0443\u00bb \u2014 \u0441 \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u043a\u0430\u0442\u043e\u0440\u043e\u043c \u0441\u0447\u0451\u0442\u0430 \u043e\u0431\u0449\u0438\u043d\u044b.";
  this.aj7 = "\u041d\u0430\u0437\u0432\u0430\u043b\u043e \u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432: \u043a\u043b\u044e\u0447 \u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d \u0432 \u0446\u0435\u043f\u043e\u0447\u043a\u0435 \u043e\u0431\u0449\u0438\u043d\u044b.";
  this.ajd = "\u042d\u0442\u0430 \u043e\u0431\u0449\u0438\u043d\u0430 \u043e\u0442\u043a\u0440\u044b\u0442\u0430 \u0434\u043b\u044f \u0432\u0441\u0435\u0445, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0435\u0451 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0438 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0435\u0433\u043e \u043d\u0435 \u0432\u044b\u0431\u0438\u0440\u0430\u044e\u0442: \u043b\u044e\u0431\u043e\u0439 \u043c\u043e\u0433 \u0431\u044b \u043f\u0440\u043e\u0433\u043e\u043b\u043e\u0441\u043e\u0432\u0430\u0442\u044c \u0437\u0430 \u0441\u0435\u0431\u044f. \u0414\u0435\u0440\u0436\u0438\u0442\u0435 \u0434\u0432\u0443\u0445 \u0443\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0438\u0445.";
  this.ajg = "\u0413\u043e\u043b\u043e\u0441 \u0435\u0441\u0442\u044c \u0442\u043e\u043b\u044c\u043a\u043e \u0443 \u0442\u0435\u0445, \u043a\u0442\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a \u043d\u0435 \u043c\u0435\u043d\u044c\u0448\u0435 \u043c\u0435\u0441\u044f\u0446\u0430.";
  this.akc = "\u041f\u0435\u0440\u0435\u043d\u0435\u0441\u0442\u0438 \u0438\u043b\u0438 \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u043a\u043e\u043f\u0438\u044e";
  this.akd = "\u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u0435 \u043a\u043e\u043f\u0438\u044e \u0432\u0441\u0435\u0439 \u043e\u0431\u0449\u0438\u043d\u044b \u2014 \u0437\u0430\u043f\u0438\u0441\u0438 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0441\u0447\u0451\u0442\u0430, \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432, \u043f\u0440\u0430\u0432\u0438\u043b\u0430, \u043a\u043b\u044e\u0447 \u043e\u0431\u0449\u0438\u043d\u044b \u2014 \u043e\u0434\u043d\u0438\u043c \u0444\u0430\u0439\u043b\u043e\u043c. \u0425\u0440\u0430\u043d\u0438\u0442\u0435 \u043a\u043e\u043f\u0438\u0438; \u0441 \u043d\u0435\u0439 \u043e\u0431\u0449\u0438\u043d\u0443 \u043c\u043e\u0436\u043d\u043e \u043f\u0435\u0440\u0435\u043d\u0435\u0441\u0442\u0438 \u043d\u0430 \u0434\u0440\u0443\u0433\u043e\u0439 \u0445\u0430\u0431 \u0438\u043b\u0438 \u043d\u0430 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0443\u0437\u0435\u043b \u2014 \u0442\u0430\u043c, \u0433\u0434\u0435 \u043e\u0431\u0449\u0438\u043d\u044b \u0441\u043e\u0437\u0434\u0430\u044e\u0442\u0441\u044f. \u041a\u043e\u0433\u0434\u0430 \u043e\u043d\u0430 \u0443\u0436\u0435 \u0442\u0430\u043c, \u0437\u0430\u043a\u0440\u043e\u0439\u0442\u0435 \u0435\u0451 \u0437\u0434\u0435\u0441\u044c.";
  this.aiS = "\u0412 \u0444\u0430\u0439\u043b\u0435 \u043a\u043b\u044e\u0447 \u043e\u0431\u0449\u0438\u043d\u044b: \u0443 \u043a\u043e\u0433\u043e \u043e\u043d \u0435\u0441\u0442\u044c, \u0442\u043e\u0442 \u043c\u043e\u0436\u0435\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u0442\u044c \u043a\u0430\u043a \u0435\u0451 \u0443\u0437\u0435\u043b. \u0425\u0440\u0430\u043d\u0438\u0442\u0435 \u0435\u0433\u043e \u043a\u0430\u043a \u043a\u043b\u044e\u0447.";
  this.amm = "\u0421\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u043a\u043e\u043f\u0438\u044e";
  this.aiT = "\u0421\u043e\u0445\u0440\u0430\u043d\u0435\u043d\u043e";
  this.aiU = "\u041a\u043e\u043f\u0438\u044f \u2014 \u0432 \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0430\u0445 \u0432\u0430\u0448\u0435\u0433\u043e \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430.";
  this.al0 = "\u041a\u043e\u043f\u0438\u044f \u043d\u0435 \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u043b\u0430\u0441\u044c.";
  this.aiz = "\u041e\u043d\u0430 \u043f\u0435\u0440\u0435\u0435\u0445\u0430\u043b\u0430: \u0437\u0430\u043a\u0440\u044b\u0442\u044c \u0437\u0434\u0435\u0441\u044c";
  this.aiE = "\u041a\u043e\u0433\u0434\u0430 \u043e\u0431\u0449\u0438\u043d\u0430 \u0443\u0436\u0435 \u043f\u0435\u0440\u0435\u043d\u0435\u0441\u0435\u043d\u0430 \u043d\u0430 \u043d\u043e\u0432\u043e\u0435 \u043c\u0435\u0441\u0442\u043e, \u0437\u0430\u043a\u0440\u043e\u0439\u0442\u0435 \u0435\u0451 \u0437\u0434\u0435\u0441\u044c: \u0441 \u044d\u0442\u043e\u0433\u043e \u043c\u043e\u043c\u0435\u043d\u0442\u0430 \u044d\u0442\u043e\u0442 \u0445\u0430\u0431 \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435 \u043c\u0435\u043d\u044f\u0435\u0442, \u0430 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0430, \u043f\u0440\u0438\u0448\u0435\u0434\u0448\u0435\u0435 \u0441\u044e\u0434\u0430, \u043e\u0442\u043f\u0440\u0430\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043f\u043e \u043d\u043e\u0432\u043e\u043c\u0443 \u0430\u0434\u0440\u0435\u0441\u0443.";
  this.akl = "\u0415\u0451 \u043d\u043e\u0432\u044b\u0439 \u0430\u0434\u0440\u0435\u0441";
  this.akm = "https://\u2026 \u2014 \u043a\u0430\u043a \u0435\u0433\u043e \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u043d\u043e\u0432\u044b\u0439 \u0445\u0430\u0431";
  this.aiD = "\u0417\u0430\u043a\u0440\u044b\u0442\u044c \u043e\u0431\u0449\u0438\u043d\u0443 \u0437\u0434\u0435\u0441\u044c? \u0421 \u044d\u0442\u043e\u0433\u043e \u043c\u043e\u043c\u0435\u043d\u0442\u0430 \u0437\u0434\u0435\u0441\u044c \u043d\u0438\u0447\u0435\u0433\u043e \u043d\u0435\u043b\u044c\u0437\u044f \u0431\u0443\u0434\u0435\u0442 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u0442\u044c.";
  this.aiF = "\u0417\u0430\u043a\u0440\u044b\u0442\u043e \u0437\u0434\u0435\u0441\u044c";
  this.aiG = "\u041f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432, \u043f\u0440\u0438\u0448\u0435\u0434\u0448\u0438\u0435 \u0441\u044e\u0434\u0430, \u0438\u0434\u0443\u0442 \u043f\u043e \u043d\u043e\u0432\u043e\u043c\u0443 \u0430\u0434\u0440\u0435\u0441\u0443.";
  this.ake = "\u041e\u0431\u0449\u0438\u043d\u0430 \u043f\u0435\u0440\u0435\u0435\u0445\u0430\u043b\u0430";
  this.ajs = "\u041f\u0435\u0440\u0435\u0439\u0442\u0438 \u0442\u0443\u0434\u0430";
  this.ai1 = "\u041f\u0435\u0440\u0435\u043d\u0435\u0441\u0442\u0438 \u043e\u0431\u0449\u0438\u043d\u0443 \u0438\u0437 \u0444\u0430\u0439\u043b\u0430";
  this.ai4 = "\u041a\u043e\u043f\u0438\u044f \u043e\u0431\u0449\u0438\u043d\u044b, \u0441\u043e\u0445\u0440\u0430\u043d\u0451\u043d\u043d\u0430\u044f \u0432 \u0435\u0451 \u043e\u0444\u0438\u0441\u0435: \u043e\u043d\u0430 \u043f\u0435\u0440\u0435\u043d\u043e\u0441\u0438\u0442\u0441\u044f \u043d\u0430 \u044d\u0442\u043e\u0442 \u0445\u0430\u0431 \u0442\u0430\u043a\u043e\u0439, \u043a\u0430\u043a\u043e\u0439 \u0431\u044b\u043b\u0430, \u2014 \u0435\u0451 \u0441\u0447\u0435\u0442\u0430, \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u0438, \u043a\u043b\u044e\u0447. \u041a\u0430\u0436\u0434\u0430\u044f \u0437\u0430\u043f\u0438\u0441\u044c \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f, \u043f\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043c \u0435\u0451 \u043f\u0440\u0438\u043d\u044f\u0442\u044c.";
  this.amW = "\u0424\u0430\u0439\u043b \u043e\u0431\u0449\u0438\u043d\u044b";
  this.ai5 = "\u041e\u0431\u0449\u0438\u043d\u0430 \u0437\u0434\u0435\u0441\u044c";
  this.ai6 = "\u0422\u0435\u043f\u0435\u0440\u044c \u0437\u0430\u043a\u0440\u043e\u0439\u0442\u0435 \u0435\u0451 \u043d\u0430 \u0441\u0442\u0430\u0440\u043e\u043c \u043c\u0435\u0441\u0442\u0435 (\u0435\u0451 \u043e\u0444\u0438\u0441: \u00ab\u041f\u0435\u0440\u0435\u043d\u0435\u0441\u0442\u0438 \u0438\u043b\u0438 \u0441\u043e\u0445\u0440\u0430\u043d\u0438\u0442\u044c \u043a\u043e\u043f\u0438\u044e\u00bb). \u0412\u0430\u0448\u0438 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0430 \u0434\u0435\u0440\u0436\u0430\u0442 \u0435\u0451 \u0441\u0447\u0435\u0442\u0430, \u043a\u0430\u043a \u0438 \u0440\u0430\u043d\u044c\u0448\u0435.";
  this.ai3 = "\u042d\u0442\u0430 \u043e\u0431\u0449\u0438\u043d\u0430 \u0443\u0436\u0435 \u043d\u0430 \u044d\u0442\u043e\u043c \u0445\u0430\u0431\u0435 \u2014 \u0438\u043b\u0438 \u043e\u0434\u0438\u043d \u0438\u0437 \u0435\u0451 \u0441\u0447\u0435\u0442\u043e\u0432.";
  this.ai0 = "\u0417\u0430\u043f\u0438\u0441\u0438 \u0444\u0430\u0439\u043b\u0430 \u043d\u0435 \u0441\u0445\u043e\u0434\u044f\u0442\u0441\u044f: \u0435\u0433\u043e \u0438\u0437\u043c\u0435\u043d\u0438\u043b\u0438 \u0438\u043b\u0438 \u043f\u043e\u0432\u0440\u0435\u0434\u0438\u043b\u0438.";
  this.ai2 = "\u042d\u0442\u043e \u043d\u0435 \u0444\u0430\u0439\u043b \u043e\u0431\u0449\u0438\u043d\u044b.";
  this.aiv = "\u0417\u0430\u043a\u0440\u044b\u0442\u044c \u0441\u0447\u0451\u0442";
  this.aix = "\u0417\u0430\u043a\u0440\u044b\u0442\u044c \u043c\u043e\u0436\u043d\u043e \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u0447\u0451\u0442 \u0441 \u043d\u0443\u043b\u0435\u0432\u044b\u043c \u0431\u0430\u043b\u0430\u043d\u0441\u043e\u043c.";
  this.aiA = "\u042d\u0442\u043e\u043c\u0443 \u0441\u0447\u0451\u0442\u0443 \u043e\u0434\u043e\u043b\u0436\u0435\u043d\u0430 \u043b\u0438\u043d\u0438\u044f \u0438\u043b\u0438 \u043e\u043d \u0435\u0451 \u043e\u0434\u043e\u043b\u0436\u0438\u043b: \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0435\u0451 \u043d\u0443\u0436\u043d\u043e \u0432\u0435\u0440\u043d\u0443\u0442\u044c.";
  this.aiy = "\u041f\u043b\u0430\u0442\u0451\u0436 \u044d\u0442\u043e\u0433\u043e \u0441\u0447\u0451\u0442\u0430 \u0435\u0449\u0451 \u0432 \u043f\u0443\u0442\u0438: \u043f\u043e\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0447\u0435\u0440\u0435\u0437 \u043c\u0438\u043d\u0443\u0442\u0443.";
  this.aiw = "\u0417\u0430\u043a\u0440\u044b\u0442\u044c \u0441\u0447\u0451\u0442? \u0418\u043c \u0431\u043e\u043b\u044c\u0448\u0435 \u043d\u0435\u043b\u044c\u0437\u044f \u0431\u0443\u0434\u0435\u0442 \u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u0442\u044c\u0441\u044f. \u0412\u0430\u0448\u0435 \u0438\u043c\u044f, \u043d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u0432\u0430\u0448\u0438\u0445 \u043f\u043b\u0430\u0442\u0435\u0436\u0435\u0439 \u0438 \u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u0438\u044f \u043d\u0430 \u0434\u043e\u0441\u043a\u0435 \u0431\u0443\u0434\u0443\u0442 \u0441\u0442\u0451\u0440\u0442\u044b; \u0437\u0430\u043f\u0438\u0441\u0438 \u0441\u0443\u043c\u043c \u043e\u0441\u0442\u0430\u043d\u0443\u0442\u0441\u044f \u2014 \u043d\u0430 \u043d\u0438\u0445 \u043e\u043f\u0438\u0440\u0430\u044e\u0442\u0441\u044f \u0437\u0430\u043f\u0438\u0441\u0438 \u0432\u0441\u0435\u0445 \u0443\u0447\u0430\u0441\u0442\u043d\u0438\u043a\u043e\u0432.";
  this.ahl = "\u0417\u0430\u043a\u0440\u044b\u0442\u043e";
