  this.aq1 = "\u0426\u0435 \u0431\u0456\u043b\u044c\u0448\u0435, \u043d\u0456\u0436 \u0446\u0435\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u043c\u043e\u0436\u0435 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u0442\u0438 \u0437\u0430 \u043e\u0434\u0438\u043d \u0440\u0430\u0437.";
  this.aq2 = "\u0426\u0435 \u0431\u0456\u043b\u044c\u0448\u0435, \u043d\u0456\u0436 \u0446\u0435\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u043c\u043e\u0436\u0435 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u0442\u0438 \u0437\u0430 \u0442\u0438\u0436\u0434\u0435\u043d\u044c.";
