  this.arQ = "\u0423 \u043c\u0456\u0441\u0446\u0456 \u2014 \u0432\u0456\u0434 3 \u0434\u043e 40 \u043c\u0430\u043b\u0438\u0445 \u043b\u0430\u0442\u0438\u043d\u0441\u044c\u043a\u0438\u0445 \u043b\u0456\u0442\u0435\u0440, \u0446\u0438\u0444\u0440 \u0430\u0431\u043e \u0434\u0435\u0444\u0456\u0441\u0456\u0432; \u0432 \u043e\u0434\u0438\u043d\u0438\u0446\u0456 \u2014 \u043b\u0456\u0442\u0435\u0440\u0438.";
  this.apO = "\u0421\u044c\u043e\u0433\u043e\u0434\u043d\u0456 \u0437\u0432\u0456\u0434\u0441\u0438 \u0431\u0456\u043b\u044c\u0448\u0435 \u043d\u0435 \u043c\u043e\u0436\u043d\u0430 \u0441\u0442\u0432\u043e\u0440\u044e\u0432\u0430\u0442\u0438 \u0433\u0440\u043e\u043c\u0430\u0434\u0438.";
  this.apM = "\u0422\u0443\u0442 \u0433\u0440\u043e\u043c\u0430\u0434\u0438 \u0441\u0442\u0432\u043e\u0440\u044e\u0454 \u043d\u0435 \u043a\u043e\u0436\u0435\u043d: \u0437\u0432\u0435\u0440\u043d\u0456\u0442\u044c\u0441\u044f \u0434\u043e \u043e\u043f\u0435\u0440\u0430\u0442\u043e\u0440\u0430 \u0446\u044c\u043e\u0433\u043e \u0441\u0430\u0439\u0442\u0443.";
  this.anT = "\u0406\u043d\u0448\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430";
  this.atj = "\u041e\u0434\u0438\u043d\u0438\u0446\u044f";
  this.arF = "\u0414\u043e \u0456\u043d\u0448\u043e\u0457 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.atu = "\u0414\u043e \u044f\u043a\u043e\u0457 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.aqR = "\u0423 \u0442\u0456\u0439 \u0433\u0440\u043e\u043c\u0430\u0434\u0456 \u043f\u043e\u043a\u0438 \u0449\u043e \u043d\u0456\u043a\u043e\u043c\u0443 \u043f\u043b\u0430\u0442\u0438\u0442\u0438.";
  this.atc = "\u041b\u0456\u043d\u0456\u0457 \u0434\u043e\u0432\u0456\u0440\u0438";
  this.aqa = "\u041b\u0456\u043d\u0456\u044f \u0434\u043e\u0432\u0456\u0440\u0438 \u043a\u0430\u0436\u0435, \u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0456\u043d\u0448\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u043c\u043e\u0436\u0435 \u0431\u0443\u0442\u0438 \u0432\u0438\u043d\u043d\u0430 \u043d\u0430\u0448\u0456\u0439. \u0422\u043e\u0434\u0456 \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0438 \u043c\u043e\u0436\u0443\u0442\u044c \u043f\u043b\u0430\u0442\u0438\u0442\u0438 \u043d\u0430\u0448\u0438\u043c, \u0430 \u043d\u0430\u0448\u0456 \u2014 \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0430\u043c, \u043d\u0430\u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0412\u041e\u041d\u0410 \u0434\u043e\u0432\u0456\u0440\u044f\u0454 \u043d\u0430\u043c. \u041f\u043b\u044e\u0441 \u043d\u0430 \u0431\u0430\u043b\u0430\u043d\u0441\u0456: \u0432\u0438\u043d\u043d\u0456 \u043c\u0438; \u043c\u0456\u043d\u0443\u0441: \u0432\u0438\u043d\u043d\u0456 \u043d\u0430\u043c.";
  this.at6 = "\u041c\u043e\u0436\u0443\u0442\u044c \u0431\u0443\u0442\u0438 \u0432\u0438\u043d\u043d\u0456 \u043d\u0430\u043c";
  this.aqJ = "\u043b\u0456\u043d\u0456\u0439 \u043f\u043e\u043a\u0438 \u0449\u043e \u043d\u0435\u043c\u0430\u0454";
  this.arw = "\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438 \u043b\u0456\u043d\u0456\u044e";
  this.aq4 = "\u0410\u0434\u0440\u0435\u0441\u0430 \u0456\u043d\u0448\u043e\u0457 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.aq5 = "\u044f\u043a \u0443 \u0457\u0457 \u043f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u0456-\u0437\u0430\u043f\u0440\u043e\u0448\u0435\u043d\u043d\u0456 \u043f\u0456\u0441\u043b\u044f ?node=";
  this.aow = "\u0417\u043c\u0456\u043d\u0438\u0442\u0438";
  this.aq7 = "\u041b\u0456\u043d\u0456\u044e \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u043e";
  this.aq6 = "\u041b\u0456\u043d\u0456\u044e \u043d\u0435 \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u043e";
  this.aq9 = "\u0422\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u0440\u0430\u0445\u0443\u0454 \u0432 \u0456\u043d\u0448\u0456\u0439 \u043e\u0434\u0438\u043d\u0438\u0446\u0456: \u043b\u0456\u043d\u0456\u0457 \u043c\u0456\u0436 \u0440\u0456\u0437\u043d\u0438\u043c\u0438 \u043e\u0434\u0438\u043d\u0438\u0446\u044f\u043c\u0438 \u0449\u0435 \u043d\u0435 \u0437\u0440\u043e\u0431\u043b\u0435\u043d\u043e.";
  this.aqQ = "\u0417\u0430 \u0446\u0456\u0454\u044e \u0430\u0434\u0440\u0435\u0441\u043e\u044e \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u043d\u0435 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u0430\u0454.";
  this.aq8 = "\u0426\u0435 \u0441\u0430\u043c\u0430 \u043d\u0430\u0448\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0430.";
  this.atv = "\u0425\u0442\u043e \u043c\u043e\u0436\u0435 \u0432\u0441\u0442\u0443\u043f\u0438\u0442\u0438";
  this.aoh = "\u043b\u0438\u0448\u0435 \u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u0441\u0430\u043c\u043e\u0437\u0430\u0439\u043d\u044f\u0442\u0456 (\u043d\u0430\u0439\u043f\u0440\u043e\u0441\u0442\u0456\u0448\u0435)";
  this.arH = "\u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438, \u044f\u043a\u0456 \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u0430\u0440\u043e\u0431\u043b\u044f\u044e\u0442\u044c, \u043f\u043e\u0442\u0456\u043c \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u044e\u0442\u044c (\u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u043e\u0432\u0430\u043d\u043e)";
  this.arG = "\u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u043e\u0441\u043e\u0431\u0438, \u0432 \u0443\u0441\u0456\u0445 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u0456 \u043b\u0456\u043d\u0456\u0457";
  this.arz = "\u0412\u0430\u0448 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u043f\u043e\u0447\u0438\u043d\u0430\u0454\u0442\u044c\u0441\u044f \u0437 \u043d\u0443\u043b\u044f \u0439 \u043d\u0438\u0436\u0447\u0435 \u043d\u0443\u043b\u044f \u043d\u0435 \u043e\u043f\u0443\u0441\u043a\u0430\u0454\u0442\u044c\u0441\u044f. \u041f\u0440\u043e\u0434\u0430\u0439\u0442\u0435 \u0449\u043e\u0441\u044c \u0430\u0431\u043e \u0432\u0438\u043a\u043e\u043d\u0430\u0439\u0442\u0435 \u0440\u043e\u0431\u043e\u0442\u0443 \u0434\u043b\u044f \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0430 \u2014 \u0456 \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u0439\u0442\u0435 \u0437\u0430\u0440\u043e\u0431\u043b\u0435\u043d\u0435.";
  this.aqI = "\u0420\u0430\u0445\u0443\u043d\u043e\u043a \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u043e\u0457 \u043e\u0441\u043e\u0431\u0438 \u0432 \u0446\u0456\u0439 \u0433\u0440\u043e\u043c\u0430\u0434\u0456 \u043d\u0435 \u043c\u0430\u0454 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u043e\u0457 \u043b\u0456\u043d\u0456\u0457: \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u0430\u0440\u043e\u0431\u0438\u0442\u0438, \u043f\u043e\u0442\u0456\u043c \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u0442\u0438.";
  this.ass = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0438";
  this.asr = "\u043f\u043e\u0447\u0430\u0442\u043a\u043e\u0432\u0438\u0439 \u0442\u0435\u043a\u0441\u0442: \u0439\u043e\u0433\u043e \u043f\u0440\u0438\u0439\u043c\u0430\u0454 \u043a\u043e\u0436\u0435\u043d \u043d\u043e\u0432\u0430\u0447\u043e\u043a. \u041f\u0435\u0440\u0448 \u043d\u0456\u0436 \u043d\u0430 \u043d\u044c\u043e\u0433\u043e \u043f\u043e\u043a\u043b\u0430\u0434\u0430\u0442\u0438\u0441\u044f, \u043f\u043e\u043a\u0430\u0436\u0456\u0442\u044c \u0439\u043e\u0433\u043e \u044e\u0440\u0438\u0441\u0442\u043e\u0432\u0456.";
  this.asS = "1. \u0413\u0440\u043e\u043c\u0430\u0434\u0430 \u0432\u0435\u0434\u0435 \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0442\u043e\u0433\u043e, \u0449\u043e \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0438 \u0434\u0430\u044e\u0442\u044c \u043e\u0434\u043d\u0435 \u043e\u0434\u043d\u043e\u043c\u0443 \u0439 \u0431\u0435\u0440\u0443\u0442\u044c \u043e\u0434\u043d\u0435 \u0432 \u043e\u0434\u043d\u043e\u0433\u043e. \u041e\u0434\u0438\u043d\u0438\u0446\u044f \u2014 \u043c\u0456\u0440\u0430 \u0432 \u0446\u044c\u043e\u043c\u0443 \u0440\u0430\u0445\u0443\u043d\u043a\u0443; \u0443 \u0446\u0456\u043d\u0430\u0445 \u0432\u043e\u043d\u0430 \u0440\u0430\u0445\u0443\u0454\u0442\u044c\u0441\u044f \u044f\u043a \u043e\u0434\u043d\u0430 \u043e\u0434\u0438\u043d\u0438\u0446\u044f \u043d\u0430\u0446\u0456\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0457 \u0432\u0430\u043b\u044e\u0442\u0438.\n2. \u041e\u0434\u0438\u043d\u0438\u0446\u0456 \u2014 \u043d\u0435 \u0433\u0440\u043e\u0448\u0456. \u041d\u0456\u0445\u0442\u043e \u0439 \u043d\u0456\u043a\u043e\u043b\u0438 \u043d\u0435 \u043f\u0440\u043e\u0434\u0430\u0454, \u043d\u0435 \u043a\u0443\u043f\u0443\u0454 \u0456 \u043d\u0435 \u043e\u0431\u043c\u0456\u043d\u044e\u0454 \u0457\u0445 \u043d\u0430 \u0433\u0440\u043e\u0448\u0456.\n3. \u0411\u0430\u043b\u0430\u043d\u0441 \u0432\u0438\u0449\u0435 \u043d\u0443\u043b\u044f \u043f\u043e\u043a\u0430\u0437\u0443\u0454, \u043d\u0430\u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0443\u0447\u0430\u0441\u043d\u0438\u043a \u0434\u0430\u0432 \u0431\u0456\u043b\u044c\u0448\u0435, \u043d\u0456\u0436 \u0443\u0437\u044f\u0432; \u0431\u0430\u043b\u0430\u043d\u0441 \u043d\u0438\u0436\u0447\u0435 \u043d\u0443\u043b\u044f \u2014 \u043d\u0430\u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0432\u0456\u043d \u0443\u0437\u044f\u0432 \u0431\u0456\u043b\u044c\u0448\u0435, \u043d\u0456\u0436 \u0434\u0430\u0432, \u0456 \u043c\u0430\u0454 \u043f\u043e\u0432\u0435\u0440\u043d\u0443\u0442\u0438 \u0433\u0440\u043e\u043c\u0430\u0434\u0456 \u0441\u0432\u043e\u0457\u043c\u0438 \u0442\u043e\u0432\u0430\u0440\u0430\u043c\u0438 \u0439 \u043f\u043e\u0441\u043b\u0443\u0433\u0430\u043c\u0438.\n4. \u041a\u043e\u0436\u0435\u043d \u0443\u0447\u0430\u0441\u043d\u0438\u043a \u043c\u0430\u0454 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u0443 \u043b\u0456\u043d\u0456\u044e \u0456 \u0441\u0442\u0435\u043b\u044e; \u0457\u0445 \u0437\u0430\u0434\u0430\u0454 \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u0439 \u043c\u043e\u0436\u0435 \u0437\u043c\u0456\u043d\u044e\u0432\u0430\u0442\u0438.\n5. \u0423\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432 \u043f\u0440\u0438\u0439\u043c\u0430\u0454 \u0433\u0440\u043e\u043c\u0430\u0434\u0430, \u0456 \u0432\u043e\u043d\u0430 \u0437\u043d\u0430\u0454 \u0457\u0445 \u0437\u0430 \u0441\u043f\u0440\u0430\u0432\u0436\u043d\u0456\u043c\u0438 \u0456\u043c\u0435\u043d\u0430\u043c\u0438.\n6. \u041f\u0440\u043e\u0434\u0430\u0436 \u0437\u0430 \u043e\u0434\u0438\u043d\u0438\u0446\u0456 \u2014 \u0446\u0435 \u043f\u0440\u043e\u0434\u0430\u0436. \u041a\u043e\u0436\u0435\u043d \u0443\u0447\u0430\u0441\u043d\u0438\u043a \u0441\u0430\u043c \u0432\u0438\u0441\u0442\u0430\u0432\u043b\u044f\u0454 \u0440\u0430\u0445\u0443\u043d\u043a\u0438 \u0439 \u0441\u0430\u043c \u0441\u043f\u043b\u0430\u0447\u0443\u0454 \u043f\u043e\u0434\u0430\u0442\u043a\u0438, \u0433\u0440\u043e\u0448\u0438\u043c\u0430, \u044f\u043a \u0456\u0437 \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u043f\u0440\u043e\u0434\u0430\u0436\u0443.\n7. \u0423\u0447\u0430\u0441\u043d\u0438\u043a \u043c\u043e\u0436\u0435 \u0432\u0438\u0439\u0442\u0438 \u0431\u0443\u0434\u044c-\u043a\u043e\u043b\u0438, \u0437\u0432\u0456\u0432\u0448\u0438 \u0431\u0430\u043b\u0430\u043d\u0441 \u0434\u043e \u043d\u0443\u043b\u044f. \u0422\u043e\u0439, \u0445\u0442\u043e \u0432\u0438\u0445\u043e\u0434\u0438\u0442\u044c \u0456\u0437 \u0431\u0430\u043b\u0430\u043d\u0441\u043e\u043c \u043d\u0438\u0436\u0447\u0435 \u043d\u0443\u043b\u044f, \u043f\u043e\u0433\u0430\u0448\u0430\u0454 \u0440\u0456\u0437\u043d\u0438\u0446\u044e \u0433\u0440\u043e\u0448\u0438\u043c\u0430 \u043f\u0440\u043e\u0442\u044f\u0433\u043e\u043c 30 \u0434\u043d\u0456\u0432.\n8. \u0413\u0440\u043e\u043c\u0430\u0434\u0430 \u043c\u043e\u0436\u0435 \u0437\u0430\u043a\u0440\u0438\u0442\u0438 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0430, \u044f\u043a\u0438\u0439 \u043f\u043e\u0440\u0443\u0448\u0443\u0454 \u0446\u0456 \u043f\u0440\u0430\u0432\u0438\u043b\u0430.";
  this.ant = "\u041f\u0440\u0438\u0439\u043c\u0430\u044e";
  this.asp = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430";
  this.ast = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043e";
  this.asq = "\u041f\u0440\u0430\u0432\u0438\u043b\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0438 \u0437\u043c\u0456\u043d\u0438\u043b\u0438\u0441\u044f: \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u0439\u0442\u0435 \u0456 \u043f\u0440\u0438\u0439\u043c\u0456\u0442\u044c \u0457\u0445 \u0437\u043d\u043e\u0432\u0443.";
  this.arr = "\u0426\u044f \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u043f\u0440\u0438\u0439\u043c\u0430\u0454 \u043b\u0438\u0448\u0435 \u0431\u0456\u0437\u043d\u0435\u0441\u0438 \u0439 \u0441\u0430\u043c\u043e\u0437\u0430\u0439\u043d\u044f\u0442\u0438\u0445.";
  this.ap4 = "\u0421\u043a\u043e\u043f\u0456\u044e\u0432\u0430\u0442\u0438 \u0432\u0438\u043f\u0438\u0441\u043a\u0443 (CSV)";
  this.asT = "\u0421\u043a\u043e\u043f\u0456\u0439\u043e\u0432\u0430\u043d\u043e";
  this.asU = "\u0412\u0430\u0448\u0456 \u0443\u0433\u043e\u0434\u0438 \u0432 \u0431\u0443\u0444\u0435\u0440\u0456 \u043e\u0431\u043c\u0456\u043d\u0443 \u0443 \u0432\u0438\u0433\u043b\u044f\u0434\u0456 CSV: \u0432\u0441\u0442\u0430\u0432\u0442\u0435 \u0457\u0445 \u0443 \u0442\u0430\u0431\u043b\u0438\u0446\u044e \u0430\u0431\u043e \u043f\u0435\u0440\u0435\u0434\u0430\u0439\u0442\u0435 \u0431\u0443\u0445\u0433\u0430\u043b\u0442\u0435\u0440\u043e\u0432\u0456. \u0423\u0433\u043e\u0434\u0430 \u0432 \u043e\u0434\u0438\u043d\u0438\u0446\u044f\u0445 \u2014 \u0446\u0435 \u043f\u0440\u043e\u0434\u0430\u0436, \u0432\u0456\u043d \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0443\u0454\u0442\u044c\u0441\u044f \u0439 \u043e\u043f\u043e\u0434\u0430\u0442\u043a\u043e\u0432\u0443\u0454\u0442\u044c\u0441\u044f \u044f\u043a \u0431\u0443\u0434\u044c-\u044f\u043a\u0438\u0439 \u0456\u043d\u0448\u0438\u0439.";
  this.ar1 = "\u0426\u0435\u0439 \u0431\u0440\u0430\u0443\u0437\u0435\u0440 \u043d\u0435 \u0434\u043e\u0437\u0432\u043e\u043b\u044f\u0454 \u0441\u0442\u043e\u0440\u0456\u043d\u0446\u0456 \u043a\u043e\u043f\u0456\u044e\u0432\u0430\u0442\u0438. \u0412\u0438\u0434\u0456\u043b\u0456\u0442\u044c \u0442\u0430\u0431\u043b\u0438\u0446\u044e \u0456 \u0441\u043a\u043e\u043f\u0456\u044e\u0439\u0442\u0435 \u0432\u0440\u0443\u0447\u043d\u0443.";
  this.aqb = "\u042f \u0432\u0442\u0440\u0430\u0442\u0438\u0432(\u043b\u0430) \u0441\u0432\u043e\u0457 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u0457";
  this.aqc = "\u041e\u0431\u0435\u0440\u0456\u0442\u044c \u0441\u0432\u0456\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a. \u0426\u0435\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u0441\u0442\u0432\u043e\u0440\u0438\u0442\u044c \u043d\u043e\u0432\u0438\u0439 \u043a\u043b\u044e\u0447 \u0456 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c \u0432\u0430\u0448\u0443 \u0433\u0440\u043e\u043c\u0430\u0434\u0443 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438, \u0449\u043e \u0446\u0435 \u0432\u0438. \u041f\u0456\u0441\u043b\u044f \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u043d\u044f \u043a\u043b\u044e\u0447 \u0442\u0440\u0438\u043c\u0430\u0442\u0438\u043c\u0435 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0447\u0435\u0440\u0435\u0437 \u0442\u0438\u0436\u0434\u0435\u043d\u044c \u2014 \u0447\u0430\u0441, \u0449\u043e\u0431 \u0432\u0438 \u0432\u0441\u0442\u0438\u0433\u043b\u0438 \u0432\u0456\u0434\u043c\u043e\u0432\u0438\u0442\u0438, \u044f\u043a\u0449\u043e \u043f\u0440\u043e\u0441\u0438\u0432 \u0445\u0442\u043e\u0441\u044c \u0456\u043d\u0448\u0438\u0439.";
  this.apV = "\u0426\u0435 \u043c\u0456\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.anX = "\u0412\u0438 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u043b\u0438 \u043f\u043e\u0432\u0435\u0440\u043d\u0443\u0442\u0438 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.ari = "\u0429\u0435 \u043d\u0456: \u0441\u0442\u0440\u043e\u043a \u043e\u0447\u0456\u043a\u0443\u0432\u0430\u043d\u043d\u044f \u043d\u0435 \u043c\u0438\u043d\u0443\u0432.";
  this.ao2 = "\u041f\u0440\u0438\u0439\u043d\u044f\u0442\u0438 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.apw = "\u0417\u0430\u0431\u0443\u0442\u0438";
  this.aop = "\u0426\u0435 \u043d\u0435 \u044f: \u0441\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438";
  this.asf = "\u0421\u043a\u0430\u0441\u043e\u0432\u0430\u043d\u043e: \u0442\u043e\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u043d\u0456\u0447\u043e\u0433\u043e \u043d\u0435 \u043e\u0442\u0440\u0438\u043c\u0430\u0454.";
  this.asd = "\u0425\u0442\u043e \u043f\u0440\u043e\u0441\u0438\u0442\u044c \u043f\u043e\u0432\u0435\u0440\u043d\u0443\u0442\u0438 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.asc = "\u041f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0439\u0442\u0435, \u043b\u0438\u0448\u0435 \u044f\u043a\u0449\u043e \u0432\u043f\u0435\u0432\u043d\u0435\u043d\u0456, \u0449\u043e \u0446\u0435 \u0443\u0447\u0430\u0441\u043d\u0438\u043a: \u043f\u043e\u0433\u043e\u0432\u043e\u0440\u0456\u0442\u044c \u0456\u0437 \u043d\u0438\u043c, \u043d\u0435 \u0432\u0456\u0440\u0442\u0435 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044e. \u0421\u0442\u0430\u0440\u0456 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u0457 \u0440\u0430\u0445\u0443\u043d\u043a\u0443 \u0449\u0435 \u0442\u0438\u0436\u0434\u0435\u043d\u044c \u043c\u043e\u0436\u0443\u0442\u044c \u0441\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438.";
  this.aqM = "\u043d\u0456\u0445\u0442\u043e \u043d\u0435 \u043f\u0440\u043e\u0441\u0438\u0442\u044c";
  this.aoZ = "\u0426\u0435 \u0432\u0456\u043d (\u0432\u043e\u043d\u0430): \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438";
  this.ase = "\u041e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u043e";
  this.apd = "\u041d\u0435 \u0432\u0456\u043d (\u0432\u043e\u043d\u0430): \u0432\u0456\u0434\u0445\u0438\u043b\u0438\u0442\u0438";
  this.ao4 = "\u0414\u043e\u0448\u043a\u0430";
  this.ao8 = "\u0429\u043e \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0438 \u043f\u0440\u043e\u043f\u043e\u043d\u0443\u044e\u0442\u044c \u0456 \u0449\u043e \u0448\u0443\u043a\u0430\u044e\u0442\u044c. \u0426\u0456\u043d\u0430 \u2014 \u0432 \u043d\u0430\u0446\u0456\u043e\u043d\u0430\u043b\u044c\u043d\u0456\u0439 \u0432\u0430\u043b\u044e\u0442\u0456; \u0447\u0430\u0441\u0442\u043a\u0430 \u043a\u0430\u0436\u0435, \u044f\u043a\u0430 \u0457\u0457 \u0447\u0430\u0441\u0442\u0438\u043d\u0430 \u0431\u0435\u0440\u0435\u0442\u044c\u0441\u044f \u043e\u0434\u0438\u043d\u0438\u0446\u044f\u043c\u0438, \u2014 \u0440\u0435\u0448\u0442\u0430 \u0441\u043f\u043b\u0430\u0447\u0443\u0454\u0442\u044c\u0441\u044f \u0433\u0440\u043e\u0448\u0438\u043c\u0430, \u043f\u043e\u0437\u0430 \u0441\u0438\u0441\u0442\u0435\u043c\u043e\u044e.";
  this.ao7 = "\u0412\u0438\u0434";
  this.arn = "\u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0454";
  this.ats = "\u0448\u0443\u043a\u0430\u0454";
  this.ao5 = "\u043f\u043e\u043a\u0438 \u0449\u043e \u043f\u043e\u0440\u043e\u0436\u043d\u044c\u043e: \u0431\u0443\u0434\u044c\u0442\u0435 \u043f\u0435\u0440\u0448\u0438\u043c";
  this.arv = "\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438";
  this.anI = "\u041f\u0440\u043e\u043f\u043e\u043d\u0443\u044e";
  this.anL = "\u0428\u0443\u043a\u0430\u044e";
  this.apq = "\u0414\u043e\u043a\u043b\u0430\u0434\u043d\u0456\u0448\u0435";
  this.as1 = "\u0426\u0456\u043d\u0430";
  this.as2 = "\u0437\u0430\u043b\u0438\u0448\u0442\u0435 \u043f\u043e\u0440\u043e\u0436\u043d\u0456\u043c: \u0437\u0430 \u0434\u043e\u043c\u043e\u0432\u043b\u0435\u043d\u0456\u0441\u0442\u044e";
  this.aoj = "\u0437\u0430 \u0434\u043e\u043c\u043e\u0432\u043b\u0435\u043d\u0456\u0441\u0442\u044e";
  this.apQ = "\u041e\u0434\u0438\u043d\u0438\u0446\u044f\u043c\u0438, %";
  this.apR = "\u044f\u043a\u0443 \u0447\u0430\u0441\u0442\u043a\u0443 \u0446\u0456\u043d\u0438 \u0432\u0438 \u0431\u0435\u0440\u0435\u0442\u0435 \u0430\u0431\u043e \u043f\u043b\u0430\u0442\u0438\u0442\u0435 \u043e\u0434\u0438\u043d\u0438\u0446\u044f\u043c\u0438: 100 \u2014 \u0443\u0441\u044e, 50 \u2014 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0443";
  this.asD = "\u0432\u0456\u0434 0 \u0434\u043e 100";
  this.as0 = "\u041e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u043d\u044f \u043d\u0430 \u0434\u043e\u0448\u0446\u0456";
  this.ar8 = "\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f";
  this.ao6 = "\u041d\u0430 \u0434\u043e\u0448\u0446\u0456 \u043d\u0435\u043c\u0430\u0454 \u043c\u0456\u0441\u0446\u044f \u0434\u043b\u044f \u0449\u0435 \u043e\u0434\u043d\u043e\u0433\u043e \u0432\u0430\u0448\u043e\u0433\u043e \u043e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u043d\u044f: \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u043d\u0456\u043c\u0456\u0442\u044c \u043e\u0434\u043d\u0435.";
  this.at1 = "\u0417\u043d\u044f\u0442\u0438 \u0437 \u0434\u043e\u0448\u043a\u0438";
  this.asE = "\u0421\u043f\u0456\u043b\u044c\u043d\u0456 \u0440\u0430\u0445\u0443\u043d\u043a\u0438";
  this.asK = "\u0420\u0430\u0445\u0443\u043d\u043e\u043a \u0440\u043e\u0434\u0438\u043d\u0438 \u0447\u0438 \u043a\u043e\u043c\u0430\u043d\u0434\u0438 \u0442\u0440\u0438\u043c\u0430\u044e\u0442\u044c \u0440\u0430\u0445\u0443\u043d\u043a\u0438 \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432, \u0430 \u043d\u0435 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u0457: \u043a\u043e\u0436\u0435\u043d \u0442\u0440\u0438\u043c\u0430\u0447 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0454\u0442\u044c\u0441\u044f \u043d\u0438\u043c \u0456\u0437 \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u0441\u0432\u043e\u0433\u043e \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u044e, \u0430 \u0432\u0442\u0440\u0430\u0447\u0435\u043d\u0438\u0439 \u0442\u0435\u043b\u0435\u0444\u043e\u043d \u0437\u0430\u043c\u0456\u043d\u044e\u0454\u0442\u044c\u0441\u044f \u043e\u0434\u0438\u043d \u0440\u0430\u0437 \u2014 \u0443 \u0432\u043b\u0430\u0441\u043d\u043e\u043c\u0443 \u0440\u0430\u0445\u0443\u043d\u043a\u0443 \u043b\u044e\u0434\u0438\u043d\u0438.";
  this.aqO = "\u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0445 \u0440\u0430\u0445\u0443\u043d\u043a\u0456\u0432 \u043f\u043e\u043a\u0438 \u043d\u0435\u043c\u0430\u0454";
  this.aqA = "\u041d\u043e\u0432\u0438\u0439 \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a";
  this.asG = "\u041d\u0430\u0437\u0432\u0430";
  this.asH = "\u0421\u043f\u0435\u0440\u0448\u0443 \u0432\u0456\u0434\u043a\u0440\u0438\u0439\u0442\u0435 \u0441\u0432\u0456\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a: \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0439 \u0440\u0430\u0445\u0443\u043d\u043e\u043a \u0442\u0440\u0438\u043c\u0430\u044e\u0442\u044c \u0440\u0430\u0445\u0443\u043d\u043a\u0438 \u0439\u043e\u0433\u043e \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432.";
  this.asJ = "\u0420\u0430\u0445\u0443\u043d\u043e\u043a \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u043e, \u0432\u0438 \u0439\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447. \u0412\u043b\u0430\u0441\u043d\u043e\u0457 \u043a\u0440\u0435\u0434\u0438\u0442\u043d\u043e\u0457 \u043b\u0456\u043d\u0456\u0457 \u0432\u0456\u043d \u043d\u0435 \u043c\u0430\u0454: \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u0454 \u0442\u0435, \u0449\u043e \u0439\u043e\u043c\u0443 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u043b\u0438, \u0430\u0431\u043e \u043b\u0456\u043d\u0456\u044e, \u044f\u043a\u0443 \u0439\u043e\u043c\u0443 \u043f\u043e\u0437\u0438\u0447\u0438\u0432 \u0443\u0447\u0430\u0441\u043d\u0438\u043a. \u0406\u043d\u0448\u0438\u0445 \u0434\u043e\u0434\u0430\u0439\u0442\u0435 \u0432 \u0440\u043e\u0437\u0434\u0456\u043b\u0456 \u00ab\u0422\u0440\u0438\u043c\u0430\u0447\u0456\u00bb.";
  this.apH = "\u0422\u0440\u0438\u043c\u0430\u0447\u0456";
  this.apI = "\u0425\u0442\u043e \u043c\u043e\u0436\u0435 \u0434\u0456\u044f\u0442\u0438 \u0432\u0456\u0434 \u0456\u043c\u0435\u043d\u0456 \u0446\u044c\u043e\u0433\u043e \u0440\u0430\u0445\u0443\u043d\u043a\u0443: \u0440\u0430\u0445\u0443\u043d\u043a\u0438 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432, \u0443 \u043a\u043e\u0436\u043d\u043e\u0433\u043e \u2014 \u0449\u043e \u0432\u0456\u043d \u043c\u043e\u0436\u0435 \u0456 \u0441\u043a\u0456\u043b\u044c\u043a\u0438. \u0422\u0440\u0438\u043c\u0430\u0447 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0454\u0442\u044c\u0441\u044f \u0440\u0430\u0445\u0443\u043d\u043a\u043e\u043c \u0456\u0437 \u0431\u0443\u0434\u044c-\u044f\u043a\u043e\u0433\u043e \u0441\u0432\u043e\u0433\u043e \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u044e.";
  this.anH = "\u0414\u043e\u0434\u0430\u0442\u0438 \u0442\u0440\u0438\u043c\u0430\u0447\u0430";
  this.apG = "\u0423\u0447\u0430\u0441\u043d\u0438\u043a";
