  this.atb = "\u041f\u043b\u0430\u0442\u0435\u0436\u0456, \u0449\u043e \u0447\u0435\u043a\u0430\u044e\u0442\u044c \u043d\u0430 \u0434\u0440\u0443\u0433\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447\u0430";
  this.ata = "\u041f\u043b\u0430\u0442\u0456\u0436 \u043f\u043e\u043d\u0430\u0434 \u043f\u043e\u0440\u0456\u0433 \u0440\u0430\u0445\u0443\u043d\u043a\u0443 \u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0454 \u043e\u0434\u0438\u043d \u0442\u0440\u0438\u043c\u0430\u0447, \u0430 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0443\u0454 \u0456\u043d\u0448\u0438\u0439. \u041d\u0435 \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u0438\u0439 \u0437\u0430 \u0442\u0438\u0436\u0434\u0435\u043d\u044c \u043f\u043b\u0430\u0442\u0456\u0436 \u0432\u0456\u0434\u043f\u0430\u0434\u0430\u0454.";
  this.arl = "\u043d\u0456\u0447\u043e\u0433\u043e \u043d\u0435 \u0447\u0435\u043a\u0430\u0454";
