  this.as6 = "\u0417\u0430\u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0432\u0430\u0432";
  this.as5 = "\u041f\u043b\u0430\u0442\u0456\u0436 \u0447\u0435\u043a\u0430\u0454 \u043d\u0430 \u0434\u0440\u0443\u0433\u043e\u0433\u043e \u0442\u0440\u0438\u043c\u0430\u0447\u0430";
