  this.asY = "\u041f\u0440\u0438\u0431\u0440\u0430\u0442\u0438 \u043a\u0430\u0440\u0442\u043a\u0443";
  this.asZ = "\u041f\u0440\u0438\u0431\u0440\u0430\u0442\u0438 \u043a\u0430\u0440\u0442\u043a\u0443? \u0412\u0456\u0434\u0442\u0435\u043f\u0435\u0440 \u043f\u0435\u0447\u0430\u0442\u043e\u043a \u043d\u0430 \u043d\u0435\u0457 \u043d\u0456\u0445\u0442\u043e \u043d\u0435 \u043e\u0442\u0440\u0438\u043c\u0430\u0454.";
  this.aoq = "\u041a\u0430\u0440\u0442\u043a\u0443 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043e";
  this.apz = "\u041f\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u0438 \u043f\u0435\u0447\u0430\u0442\u043a\u0443";
  this.apA = "\u041d\u0435\u0445\u0430\u0439 \u043f\u043e\u043a\u0443\u043f\u0435\u0446\u044c \u043d\u0430\u0432\u0435\u0434\u0435 \u043a\u0430\u043c\u0435\u0440\u0443 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0430 \u043d\u0430 \u0446\u0435\u0439 \u043a\u043e\u0434: \u0432\u0456\u0434\u043a\u0440\u0438\u0454\u0442\u044c\u0441\u044f \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043e\u043a, \u0456 \u043f\u0435\u0447\u0430\u0442\u043a\u0430 \u0437\u2019\u044f\u0432\u0438\u0442\u044c\u0441\u044f \u043d\u0430 \u0439\u043e\u0433\u043e \u043a\u0430\u0440\u0442\u0446\u0456. \u041a\u043e\u0434 \u0434\u0456\u0454 \u043e\u0434\u0438\u043d \u0440\u0430\u0437, \u0434\u0435\u0441\u044f\u0442\u044c \u0445\u0432\u0438\u043b\u0438\u043d.";
  this.apx = "\u0412\u0438\u0434\u0430\u0442\u0438 \u0432\u0438\u043d\u0430\u0433\u043e\u0440\u043e\u0434\u0443";
  this.apy = "\u041f\u043e\u043a\u0443\u043f\u0435\u0446\u044c \u0456\u0437 \u0437\u0430\u043f\u043e\u0432\u043d\u0435\u043d\u043e\u044e \u043a\u0430\u0440\u0442\u043a\u043e\u044e \u0441\u043a\u0430\u043d\u0443\u0454 \u0446\u0435\u0439 \u043a\u043e\u0434: \u0432\u0438\u043d\u0430\u0433\u043e\u0440\u043e\u0434\u0430 \u0441\u043f\u0438\u0441\u0443\u0454\u0442\u044c\u0441\u044f \u0437 \u043a\u0430\u0440\u0442\u043a\u0438, \u0456 \u0439\u043e\u0433\u043e \u0435\u043a\u0440\u0430\u043d \u0446\u0435 \u043f\u043e\u043a\u0430\u0437\u0443\u0454. \u041a\u043e\u0434 \u0434\u0456\u0454 \u043e\u0434\u0438\u043d \u0440\u0430\u0437, \u0434\u0435\u0441\u044f\u0442\u044c \u0445\u0432\u0438\u043b\u0438\u043d.";
  this.aqD = "\u041d\u043e\u0432\u0438\u0439 \u043a\u043e\u0434";
  this.asO = "\u041f\u0435\u0447\u0430\u0442\u043a\u0430";
  this.aso = "\u0412\u0438\u043d\u0430\u0433\u043e\u0440\u043e\u0434\u0430";
  this.aoT = "\u0426\u0435\u0439 \u043a\u043e\u0434 \u0443\u0436\u0435 \u0432\u0438\u043a\u043e\u0440\u0438\u0441\u0442\u0430\u043d\u043e: \u043f\u043e\u043f\u0440\u043e\u0441\u0456\u0442\u044c \u043d\u043e\u0432\u0438\u0439.";
  this.aoS = "\u0426\u0435\u0439 \u043a\u043e\u0434 \u0437\u0430\u0441\u0442\u0430\u0440\u0456\u0432: \u043f\u043e\u043f\u0440\u043e\u0441\u0456\u0442\u044c \u043d\u043e\u0432\u0438\u0439.";
  this.aoR = "\u0426\u0435 \u043d\u0435 \u043a\u043e\u0434 \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0443.";
  this.ar2 = "\u041a\u0430\u0440\u0442\u043a\u0443 \u0449\u0435 \u043d\u0435 \u0437\u0430\u043f\u043e\u0432\u043d\u0435\u043d\u043e.";
  this.aqP = "\u0426\u0435\u0439 \u043c\u0430\u0433\u0430\u0437\u0438\u043d \u0437\u0430\u0440\u0430\u0437 \u043d\u0435 \u043c\u0430\u0454 \u043a\u0430\u0440\u0442\u043a\u0438.";
  this.arA = "\u0426\u0435 \u043a\u043e\u0434 \u0432\u0430\u0448\u043e\u0433\u043e \u0432\u043b\u0430\u0441\u043d\u043e\u0433\u043e \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0443.";
  this.arq = "\u0426\u0456\u0454\u044e \u0433\u0440\u043e\u043c\u0430\u0434\u043e\u044e \u043a\u0435\u0440\u0443\u0454 \u043e\u0434\u0438\u043d \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439. \u042f\u043a\u0449\u043e \u0432\u0456\u043d \u0437\u0430\u0433\u0443\u0431\u0438\u0442\u044c\u0441\u044f, \u043d\u0456\u0445\u0442\u043e \u043d\u0435 \u0437\u043c\u043e\u0436\u0435 \u043f\u0440\u0438\u0439\u043c\u0430\u0442\u0438 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432 \u0456 \u0437\u0430\u0434\u0430\u0432\u0430\u0442\u0438 \u043b\u0456\u043c\u0456\u0442\u0438, \u0434\u043e\u043a\u0438 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0438 \u043d\u0435 \u043e\u0431\u0435\u0440\u0443\u0442\u044c \u043d\u043e\u0432\u043e\u0433\u043e \u043a\u0435\u0440\u0456\u0432\u043d\u0438\u043a\u0430. \u0414\u043e\u0434\u0430\u0439\u0442\u0435 \u0434\u0440\u0443\u0433\u043e\u0433\u043e \u043a\u0435\u0440\u0456\u0432\u043d\u0438\u043a\u0430 \u0437\u0430\u0440\u0430\u0437 \u2014 \u0456\u043d\u0448\u0438\u0439 \u0441\u0432\u0456\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u0430\u0431\u043e \u043b\u044e\u0434\u0438\u043d\u0443, \u044f\u043a\u0456\u0439 \u0434\u043e\u0432\u0456\u0440\u044f\u0454\u0442\u0435.";
  this.aqf = "\u041a\u0435\u0440\u0456\u0432\u043d\u0438\u043a\u0438";
  this.apk = "\u041e\u0431\u0440\u0430\u0442\u0438 \u043a\u0435\u0440\u0456\u0432\u043d\u0438\u043a\u0430";
  this.apn = "\u0421\u043a\u0456\u043b\u044c\u043a\u0438 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432 \u043d\u0430\u0437\u0432\u0430\u043b\u0438";
  this.apl = "\u043a\u043b\u044e\u0447\u0430 \u0449\u0435 \u043d\u0456\u0445\u0442\u043e \u043d\u0435 \u043d\u0430\u0437\u0432\u0430\u0432";
  this.api = "\u041a\u043b\u044e\u0447 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u044e \u043d\u043e\u0432\u043e\u0433\u043e \u043a\u0435\u0440\u0456\u0432\u043d\u0438\u043a\u0430";
  this.apj = "\u043a\u043b\u044e\u0447 \u0446\u044c\u043e\u0433\u043e \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u044e, \u044f\u043a\u0449\u043e \u043d\u0435 \u0432\u043f\u0438\u0441\u0430\u0442\u0438 \u0456\u043d\u0448\u0438\u0439: \u0439\u043e\u0433\u043e \u043f\u043e\u043a\u0430\u0437\u0430\u043d\u043e \u0442\u0430\u043c \u0443 \u00ab\u0414\u043e\u0434\u0430\u0442\u0438 \u0446\u0435\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439\u00bb";
  this.apo = "\u041d\u0430\u0437\u0432\u0430\u0442\u0438 \u0446\u0435\u0439 \u043a\u043b\u044e\u0447";
  this.aph = "\u041d\u043e\u0432\u0438\u0439 \u043a\u0435\u0440\u0456\u0432\u043d\u0438\u043a \u0442\u0435\u043f\u0435\u0440 \u043a\u0435\u0440\u0443\u0454. \u041d\u0430 \u0442\u043e\u043c\u0443 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u0457: \u00ab\u0420\u0430\u0445\u0443\u043d\u043a\u0438\u00bb, \u00ab\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438 \u0430\u0431\u043e \u0434\u043e\u0434\u0430\u0442\u0438 \u0449\u0435\u00bb, \u00ab\u0414\u043e\u0434\u0430\u0442\u0438 \u0446\u0435\u0439 \u043f\u0440\u0438\u0441\u0442\u0440\u0456\u0439 \u0434\u043e \u043c\u043e\u0433\u043e \u0440\u0430\u0445\u0443\u043d\u043a\u0443\u00bb \u2014 \u0437 \u0456\u0434\u0435\u043d\u0442\u0438\u0444\u0456\u043a\u0430\u0442\u043e\u0440\u043e\u043c \u0440\u0430\u0445\u0443\u043d\u043a\u0443 \u0433\u0440\u043e\u043c\u0430\u0434\u0438.";
  this.apg = "\u041d\u0430\u0437\u0432\u0430\u043b\u043e \u0434\u043e\u0441\u0442\u0430\u0442\u043d\u044c\u043e \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432: \u043a\u043b\u044e\u0447 \u043e\u0433\u043e\u043b\u043e\u0448\u0435\u043d\u043e \u0432 \u043b\u0430\u043d\u0446\u044e\u0436\u043a\u0443 \u0433\u0440\u043e\u043c\u0430\u0434\u0438.";
  this.apm = "\u0426\u044f \u0433\u0440\u043e\u043c\u0430\u0434\u0430 \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u0430 \u0434\u043b\u044f \u0432\u0441\u0456\u0445, \u0442\u043e\u043c\u0443 \u0457\u0457 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0438 \u043a\u0435\u0440\u0456\u0432\u043d\u0438\u043a\u0430 \u043d\u0435 \u043e\u0431\u0438\u0440\u0430\u044e\u0442\u044c: \u0431\u0443\u0434\u044c-\u0445\u0442\u043e \u043c\u0456\u0433 \u0431\u0438 \u043f\u0440\u043e\u0433\u043e\u043b\u043e\u0441\u0443\u0432\u0430\u0442\u0438 \u0437\u0430 \u0441\u0435\u0431\u0435. \u0422\u0440\u0438\u043c\u0430\u0439\u0442\u0435 \u0434\u0432\u043e\u0445 \u043a\u0435\u0440\u0456\u0432\u043d\u0438\u043a\u0456\u0432.";
  this.app = "\u0413\u043e\u043b\u043e\u0441 \u043c\u0430\u044e\u0442\u044c \u043b\u0438\u0448\u0435 \u0442\u0456, \u0445\u0442\u043e \u0454 \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u043e\u043c \u0449\u043e\u043d\u0430\u0439\u043c\u0435\u043d\u0448\u0435 \u043c\u0456\u0441\u044f\u0446\u044c.";
  this.aql = "\u041f\u0435\u0440\u0435\u043d\u0435\u0441\u0442\u0438 \u0430\u0431\u043e \u0437\u0431\u0435\u0440\u0435\u0433\u0442\u0438 \u043a\u043e\u043f\u0456\u044e";
  this.aqm = "\u0417\u0431\u0435\u0440\u0435\u0436\u0456\u0442\u044c \u043a\u043e\u043f\u0456\u044e \u0432\u0441\u0456\u0454\u0457 \u0433\u0440\u043e\u043c\u0430\u0434\u0438 \u2014 \u0437\u0430\u043f\u0438\u0441\u0438 \u043a\u043e\u0436\u043d\u043e\u0433\u043e \u0440\u0430\u0445\u0443\u043d\u043a\u0443, \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0456\u0432, \u043f\u0440\u0430\u0432\u0438\u043b\u0430, \u043a\u043b\u044e\u0447 \u0433\u0440\u043e\u043c\u0430\u0434\u0438 \u2014 \u043e\u0434\u043d\u0438\u043c \u0444\u0430\u0439\u043b\u043e\u043c. \u0417\u0431\u0435\u0440\u0456\u0433\u0430\u0439\u0442\u0435 \u043a\u043e\u043f\u0456\u0457; \u0437 \u043d\u0435\u044e \u0433\u0440\u043e\u043c\u0430\u0434\u0443 \u043c\u043e\u0436\u043d\u0430 \u043f\u0435\u0440\u0435\u043d\u0435\u0441\u0442\u0438 \u043d\u0430 \u0456\u043d\u0448\u0438\u0439 \u0445\u0430\u0431 \u0430\u0431\u043e \u043d\u0430 \u0432\u043b\u0430\u0441\u043d\u0438\u0439 \u0432\u0443\u0437\u043e\u043b \u2014 \u0442\u0430\u043c, \u0434\u0435 \u0433\u0440\u043e\u043c\u0430\u0434\u0438 \u0441\u0442\u0432\u043e\u0440\u044e\u044e\u0442\u044c\u0441\u044f. \u041a\u043e\u043b\u0438 \u0432\u043e\u043d\u0430 \u0432\u0436\u0435 \u0442\u0430\u043c, \u0437\u0430\u043a\u0440\u0438\u0439\u0442\u0435 \u0457\u0457 \u0442\u0443\u0442.";
  this.ap1 = "\u0423 \u0444\u0430\u0439\u043b\u0456 \u043a\u043b\u044e\u0447 \u0433\u0440\u043e\u043c\u0430\u0434\u0438: \u0443 \u043a\u043e\u0433\u043e \u0432\u0456\u043d \u0454, \u0442\u043e\u0439 \u043c\u043e\u0436\u0435 \u0434\u0456\u044f\u0442\u0438 \u044f\u043a \u0457\u0457 \u0432\u0443\u0437\u043e\u043b. \u0417\u0431\u0435\u0440\u0456\u0433\u0430\u0439\u0442\u0435 \u0439\u043e\u0433\u043e \u044f\u043a \u043a\u043b\u044e\u0447.";
  this.asv = "\u0417\u0431\u0435\u0440\u0435\u0433\u0442\u0438 \u043a\u043e\u043f\u0456\u044e";
  this.ap2 = "\u0417\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043e";
  this.ap3 = "\u041a\u043e\u043f\u0456\u044f \u2014 \u0443 \u0437\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0435\u043d\u043d\u044f\u0445 \u0432\u0430\u0448\u043e\u0433\u043e \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u044e.";
  this.ar9 = "\u041a\u043e\u043f\u0456\u044e \u043d\u0435 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043e.";
  this.aoI = "\u0412\u043e\u043d\u0430 \u043f\u0435\u0440\u0435\u0457\u0445\u0430\u043b\u0430: \u0437\u0430\u043a\u0440\u0438\u0442\u0438 \u0442\u0443\u0442";
  this.aoN = "\u041a\u043e\u043b\u0438 \u0433\u0440\u043e\u043c\u0430\u0434\u0443 \u0432\u0436\u0435 \u043f\u0435\u0440\u0435\u043d\u0435\u0441\u0435\u043d\u043e \u043d\u0430 \u043d\u043e\u0432\u0435 \u043c\u0456\u0441\u0446\u0435, \u0437\u0430\u043a\u0440\u0438\u0439\u0442\u0435 \u0457\u0457 \u0442\u0443\u0442: \u0432\u0456\u0434\u0442\u0435\u043f\u0435\u0440 \u0446\u0435\u0439 \u0445\u0430\u0431 \u043d\u0456\u0447\u043e\u0433\u043e \u043d\u0435 \u0437\u043c\u0456\u043d\u044e\u0454, \u0430 \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043e\u043a \u043a\u043e\u0436\u043d\u043e\u0433\u043e \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0430, \u0449\u043e \u043f\u0440\u0438\u0439\u0434\u0435 \u0441\u044e\u0434\u0438, \u0432\u0456\u0434\u043f\u0440\u0430\u0432\u043b\u044f\u0454\u0442\u044c\u0441\u044f \u0437\u0430 \u043d\u043e\u0432\u043e\u044e \u0430\u0434\u0440\u0435\u0441\u043e\u044e.";
  this.aqu = "\u0407\u0457 \u043d\u043e\u0432\u0430 \u0430\u0434\u0440\u0435\u0441\u0430";
  this.aqv = "https://\u2026 \u2014 \u044f\u043a \u0457\u0457 \u043f\u043e\u043a\u0430\u0437\u0443\u0454 \u043d\u043e\u0432\u0438\u0439 \u0445\u0430\u0431";
  this.aoM = "\u0417\u0430\u043a\u0440\u0438\u0442\u0438 \u0433\u0440\u043e\u043c\u0430\u0434\u0443 \u0442\u0443\u0442? \u0412\u0456\u0434\u0442\u0435\u043f\u0435\u0440 \u0442\u0443\u0442 \u043d\u0456\u0447\u043e\u0433\u043e \u043d\u0435 \u043c\u043e\u0436\u043d\u0430 \u0431\u0443\u0434\u0435 \u0437\u0430\u043f\u043b\u0430\u0442\u0438\u0442\u0438.";
